mapper.update:
UPDATE chat_conversations SET updated_at=SYSDATE,
  medication_id=#{medicationId,jdbcType=VARCHAR}
WHERE conversation_id=#{conversationId} AND user_id=#{userId}

mapper.select:
SELECT conversation_id AS "conversationId",title AS "title",medication_id AS "medicationId",
  TO_CHAR(FROM_TZ(CAST(created_at AS TIMESTAMP),'UTC') AT TIME ZONE 'Asia/Seoul','YYYY-MM-DD HH24:MI') AS "createdAt",TO_CHAR(FROM_TZ(CAST(updated_at AS TIMESTAMP),'UTC') AT TIME ZONE 'Asia/Seoul','YYYY-MM-DD HH24:MI') AS "updatedAt"
FROM chat_conversations WHERE conversation_id=#{conversationId} AND user_id=#{userId}
